import java.util.concurrent.Semaphore;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DatabaseConnectionThrottler {
    private final Semaphore semaphore;
    private final int maxConnections;

    public DatabaseConnectionThrottler(int maxConnections) {
        this.maxConnections = maxConnections;
        // Fair semaphore to prevent thread starvation under heavy load
        this.semaphore = new Semaphore(maxConnections, true);
    }

    public void executeQuery(Runnable queryTask) {
        try {
            semaphore.acquire();
            try {
                // Critical section: execute database operation
                queryTask.run();
            } finally {
                semaphore.release();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Thread was interrupted while waiting for database connection.");
        }
    }
}
